class Solution {
    public boolean isGoodArray(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (gcd(nums[i], nums[j]) == 1) return true;
        return false;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

